(async () => {
  const { readFileSync, writeFileSync, mkdirSync, existsSync } = await import('node:fs');
  const inputPath = process.env.INPUT_PATH;
  const outputPath = process.env.OUTPUT_PATH;
  if (!inputPath) throw new Error('Missing INPUT_PATH env var');
  if (!outputPath) throw new Error('Missing OUTPUT_PATH env var');
  if (!existsSync(inputPath)) throw new Error('Input file does not exist: ' + inputPath);
  const yamlText = readFileSync(inputPath, 'utf8');
  globalThis.yamlText = yamlText;
  const path = await import('node:path');
  const dir = path.dirname(outputPath);
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
})();

(async () => {
  const { parseYAML, stringifyTOML } = await import('confbox');
  const yamlObj = parseYAML(globalThis.yamlText);
  const tomlText = stringifyTOML(yamlObj);
  globalThis.tomlText = tomlText;
  const { writeFileSync } = await import('node:fs');
  const outputPath = process.env.OUTPUT_PATH;
  writeFileSync(outputPath, tomlText, 'utf8');
})();
